function sheet(name,title,sub){const s=wb.worksheets.add(name);s.showGridLines=false;s.getRange('A1:H3').format.columnWidth=23;s.getRange('A1:H1').merge();s.getRange('A1').values=[[title]];s.getRange('A1:H1').format={font:{name:'Arial',size:17,bold:true,color:'#172B4D'},rowHeight:30};s.getRange('A2:H3').merge();s.getRange('A2').values=[[sub]];s.getRange('A2:H3').format={font:{name:'Arial',size:10,color:'#526176'},wrapText:true,verticalAlignment:'center',rowHeight:20};sheets.push({name,s});return s;}
function band(s,r,v){const q=s.getRangeByIndexes(r,0,1,8);q.merge();q.values=[[v]];q.format={font:{name:'Arial',size:12,bold:true,color:'#172B4D'},fill:'#E7EDF4',rowHeight:28};}
function note(s,r,label,value){s.getCell(r,0).values=[[label]];s.getRangeByIndexes(r,1,1,7).merge();s.getCell(r,1).values=[[value]];s.getRangeByIndexes(r,0,1,8).format={font:{name:'Arial',size:10,color:'#344054'},wrapText:true,verticalAlignment:'top',rowHeight:Math.max(32,Math.ceil(value.length/140)*15+10)};s.getCell(r,0).format.font.bold=true;}
function table(s,r,cols,rows,height=68){if(rows.some(v=>v.length!==cols.length))throw Error('bad shape '+cols);s.getRangeByIndexes(r,0,1,cols.length).values=[cols];s.getRangeByIndexes(r+1,0,rows.length,cols.length).values=rows;s.getRangeByIndexes(r,0,rows.length+1,cols.length).format={font:{name:'Arial',size:10},wrapText:true,verticalAlignment:'top',rowHeight:height};s.getRangeByIndexes(r,0,1,cols.length).format={font:{name:'Arial',size:10,bold:true,color:'#FFFFFF'},fill:'#243B53',rowHeight:36};s.tables.add(`A${r+1}:${String.fromCharCode(64+cols.length)}${r+rows.length+1}`,true,'HRTable'+(++tn));cols.forEach((c,i)=>{const q=s.getRangeByIndexes(r+1,i,rows.length,1);if(c.includes('Rp'))q.setNumberFormat('#,##0;[Red](#,##0);"—"');if(rows.some(x=>x[i]instanceof Date))q.setNumberFormat('dd mmm yyyy');});return r+rows.length+2;}
